tool_input.command:
mkdir -p /tmp/apireview && cat > /tmp/apireview/probe.mjs <<'EOF'
const root = process.argv[2];
const { handle } = await import(root + '/src/api.js');
const { reset, queryLog } = await import(root + '/src/db.js');
const { dueReminders } = await import(root + '/src/scheduler.js');

const create = (body) => handle({ method: 'POST', path: '/reminders', body });

// 1. IST 09:00 reminder: when does the scheduler fire it?
reset();
const r = create({ userId: 'u1', text: 'call mum', at: '2026-03-01T09:00', tzOffsetMin: 330 }).body;
console.log('due_ms', new Date(r.due_ms).toISOString());
for (const t of ['2026-02-28T22:00:00Z', '2026-03-01T03:29:00Z', '2026-03-01T03:30:00Z']) {
  console.log('fires at', t, '?', dueReminders([r], Date.parse(t)).length === 1);
}
const ny = create({ userId: 'u1', text: 'ny', at: '2026-03-01T09:00', tzOffsetMin: -300 }).body;
console.log('NY due_ms', new Date(ny.due_ms).toISOString(), 'fires at 14:00Z?', dueReminders([ny], Date.parse('2026-03-01T14:00:00Z')).length === 1, 'fires at 19:00Z?', dueReminders([ny], Date.parse('2026-03-01T19:00:00Z')).length === 1);

// 2. Malformed at
for (const at of ['2026-03-01T09:00:00', '2026-03-01 09:00', 'tomorrow', '2026-03-01T09:00Z']) {
  const res = create({ userId: 'u1', text: 'x', at });
  console.log('at=', JSON.stringify(at), '->', res.status, 'due_ms', res.body.due_ms);
}
const s = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 'abc' });
console.log('tzOffsetMin=abc ->', s.status, s.body.due_ms);

// 3. Search injection / quotes
reset();
create({ userId: 'u1', text: "mine", at: '2026-03-01T09:00' });
create({ userId: 'u2', text: "secret of u2", at: '2026-03-01T09:00' });
const tryS = (query) => { try { const r = handle({ method: 'GET', path: '/reminders/search', query }); return r.status + ' ' + JSON.stringify(r.body.map(x=>x.user_id+':'+x.text)); } catch (e) { return 'THROW ' + e.message; } };
console.log('normal', tryS({ userId: 'u1', q: 'min' }));
console.log("apostrophe", tryS({ userId: 'u1', q: "mum's" }));
console.log("inject userId", tryS({ userId: "u2' AND text LIKE '%", q: '' }));
console.log("cross-user via userId", tryS({ userId: "u2", q: 'secret' }));
console.log('last sql', queryLog.at(-1).sql);

// 4. Missing query
try { handle({ method: 'GET', path: '/reminders' }); console.log('no query ok'); } catch (e) { console.log('GET /reminders without query THROW', e.message); }
try { console.log('no userId', JSON.stringify(handle({ method: 'GET', path: '/reminders', query: {} }))); } catch (e) { console.log('THROW', e.message); }

// 5. Delete anyone's
const id = create({ userId: 'u2', text: 'z', at: '2026-03-01T09:00' }).body.id;
console.log('delete other user reminder', handle({ method: 'DELETE', path: '/reminders/' + id }).status);
EOF
node /tmp/apireview/probe.mjs "$PWD"; echo; node --test test/ 2>&1 | tail -12

