const s = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 'abc' });
console.log('tzOffsetMin=abc ->', s.status, s.body.due_ms);

// 3. Search injection / quotes
reset();
create({ userId: 'u1', text: 'mine', at: '2026-03-01T09:00' });
create({ userId: 'u2', text: 'secret of u2', at: '2026-03-01T09:00' });
const tryS = (query) => {
  try {
    const res = handle({ method: 'GET', path: '/reminders/search', query });
    return res.status + ' ' + JSON.stringify(res.body.map((x) => x.user_id + ':' + x.text));
  } catch (e) { return 'THROW ' + e.message; }
};
console.log('search normal', tryS({ userId: 'u1', q: 'min' }));
console.log('search apostrophe', tryS({ userId: 'u1', q: "mum's" }));
console.log('search no q', tryS({ userId: 'u1' }));
console.log('search other user', tryS({ userId: 'u2', q: 'secret' }));
console.log('last sql', queryLog.at(-1).sql);

// 4. Missing query
try { handle({ method: 'GET', path: '/reminders' }); console.log('no query ok'); }
catch (e) { console.log('GET /reminders without query THROW', e.message); }

// 5. Delete anyone's
const id = create({ userId: 'u2', text: 'z', at: '2026-03-01T09:00' }).body.id;
console.log('delete other user reminder (no userId given) ->', handle({ method: 'DELETE', path: '/reminders/' + id }).status);

